mod harness;
use std::{sync::Arc, fmt};
use datafusion::{arrow::{array::{Int64Array,RecordBatch}, datatypes::{Schema,Field,DataType}}, common::{Result,DataFusionError,config::ConfigOptions}, execution::{TaskContext,SessionStateBuilder}, physical_plan::{ExecutionPlan,PlanProperties,DisplayAs,DisplayFormatType,empty::EmptyExec,metrics::{ExecutionPlanMetricsSet,MetricsSet,MetricBuilder},stream::RecordBatchStreamAdapter}, prelude::SessionContext};
use datafusion_tracing::{InstrumentationOptions,instrument_with_info_spans};
use futures::{StreamExt,stream};
use tracing::Instrument;
use futures::FutureExt;
use tracing::instrument::WithSubscriber;
use tracing_subscriber::{prelude::*,fmt::format::FmtSpan};
#[derive(Debug)] struct ProbeExec { inner: EmptyExec, metrics: ExecutionPlanMetricsSet, mode: String }
impl DisplayAs for ProbeExec {fn fmt_as(&self,_:DisplayFormatType,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"ProbeExec")}}
impl ExecutionPlan for ProbeExec {
 fn apply_expressions(&self,_:&mut dyn FnMut(&Arc<dyn datafusion::physical_expr::PhysicalExpr>)->Result<datafusion::common::tree_node::TreeNodeRecursion>)->Result<datafusion::common::tree_node::TreeNodeRecursion>{Ok(datafusion::common::tree_node::TreeNodeRecursion::Continue)}
 fn name(&self)->&str {"ProbeExec"}
 fn properties(&self)->&Arc<PlanProperties>{self.inner.properties()}
 fn children(&self)->Vec<&Arc<dyn ExecutionPlan>>{vec![]}
 fn with_new_children(self:Arc<Self>,c:Vec<Arc<dyn ExecutionPlan>>)->Result<Arc<dyn ExecutionPlan>>{assert!(c.is_empty());Ok(self)}
 fn metrics(&self)->Option<MetricsSet>{Some(self.metrics.clone_inner())}
 fn execute(&self,_:usize,_:Arc<TaskContext>)->Result<datafusion::execution::SendableRecordBatchStream>{
  MetricBuilder::new(&self.metrics).counter("n06_custom",0).add(7);
  let batch=RecordBatch::try_new(self.schema(),vec![Arc::new(Int64Array::from(vec![1,2,3]))])?;
  let count=MetricBuilder::new(&self.metrics).output_rows(0);
  let mut items=vec![Ok(batch.clone()),Ok(batch)];
  if self.mode=="error" {items[1]=Err(DataFusionError::Execution("deliberate-poll-error".into()));}
  let s=stream::iter(items).map(move |x|{if let Ok(b)=&x{count.add(b.num_rows());}x});
  Ok(Box::pin(RecordBatchStreamAdapter::new(self.schema(),s)))
 }
}
struct ContextTracer;
impl datafusion::common::runtime::JoinSetTracer for ContextTracer {
 fn trace_future(&self,f:futures::future::BoxFuture<'static,Box<dyn std::any::Any+Send>>)->futures::future::BoxFuture<'static,Box<dyn std::any::Any+Send>>{
  let span=tracing::Span::current(); let dispatch=tracing::dispatcher::get_default(Clone::clone);
  f.instrument(span).with_subscriber(dispatch).boxed()
 }
 fn trace_block(&self,f:Box<dyn FnOnce()->Box<dyn std::any::Any+Send>+Send>)->Box<dyn FnOnce()->Box<dyn std::any::Any+Send>+Send>{
  let span=tracing::Span::current(); let dispatch=tracing::dispatcher::get_default(Clone::clone);
  Box::new(move||tracing::dispatcher::with_default(&dispatch,||span.in_scope(f)))
 }
}
#[derive(Debug)]struct Planner(Arc<std::sync::atomic::AtomicUsize>);
#[async_trait::async_trait]
impl datafusion::execution::context::QueryPlanner for Planner{
 async fn create_physical_plan(&self,p:&datafusion::logical_expr::LogicalPlan,s:&dyn datafusion::catalog::Session)->Result<Arc<dyn ExecutionPlan>>{
  self.0.fetch_add(1,std::sync::atomic::Ordering::SeqCst);
  use datafusion::physical_planner::PhysicalPlanner;
  datafusion::physical_planner::DefaultPhysicalPlanner::default().create_physical_plan(p,s).await
 }
}
#[tokio::main(flavor="multi_thread",worker_threads=2)] async fn main()->Result<()> {
 let mode=std::env::args().nth(1).unwrap();
 let buffer=harness::Buffer::new();
 let subscriber=tracing_subscriber::registry().with(tracing_subscriber::fmt::layer().json().without_time().with_span_events(FmtSpan::CLOSE).with_writer(buffer.clone()));
 tracing::subscriber::set_global_default(subscriber).unwrap();
 if mode=="tasks-fixed"{datafusion::common::runtime::set_join_set_tracer(&ContextTracer).unwrap();}
 let opts=InstrumentationOptions::builder().record_metrics(true).build();
 let rule=if mode=="declared"{instrument_with_info_spans!(target:"pse_probe",options:opts,datafusion.metrics.n06_custom=tracing::field::Empty)}else{instrument_with_info_spans!(target:"pse_probe",options:opts)};
 if mode=="planner" {
  use std::sync::atomic::{AtomicUsize,Ordering};
  use datafusion::logical_expr::{create_udf,Volatility,ColumnarValue};
  let calls=Arc::new(AtomicUsize::new(0)); let udf_calls=Arc::new(AtomicUsize::new(0));
  let seen=udf_calls.clone();
  let udf=Arc::new(create_udf("caller_function",vec![],DataType::Int64,Volatility::Volatile,Arc::new(move |_|{seen.fetch_add(1,Ordering::SeqCst);Ok(ColumnarValue::Scalar(datafusion::common::ScalarValue::Int64(Some(731))))})));
  let extension=Arc::new(219_u64);
  let base=SessionStateBuilder::new().with_default_features().with_scalar_functions(vec![udf.clone()]).with_query_planner(Arc::new(Planner(calls.clone()))).with_config(datafusion::execution::config::SessionConfig::new().with_extension(extension.clone())).with_physical_optimizer_rule(rule).build();
  let state=datafusion_tracing::instrument_rules_with_info_spans!(target:"pse_probe",options:datafusion_tracing::RuleInstrumentationOptions::phase_only(),state:base);
  let retained_udf=Arc::ptr_eq(state.scalar_functions().get("caller_function").unwrap(),&udf);
  let retained_extension=Arc::ptr_eq(&state.config().get_extension::<u64>().unwrap(),&extension);
  let ctx=SessionContext::new_with_state(state);
  let df=ctx.sql("SELECT caller_function()").await?;
  let plan=df.create_physical_plan().await?;
  let before=calls.load(Ordering::SeqCst); let pre_udf=udf_calls.load(Ordering::SeqCst);
  let values=datafusion::physical_plan::collect(plan,ctx.task_ctx()).await?;
  eprintln!("{}",serde_json::json!({"planner_calls":before,"udf_calls_at_planning":pre_udf,"udf_calls_at_completion":udf_calls.load(Ordering::SeqCst),"retained_udf":retained_udf,"retained_extension":retained_extension,"result":values[0].column(0).as_any().downcast_ref::<Int64Array>().unwrap().value(0)}));
 } else if mode=="tasks" || mode=="tasks-fixed" {
  let root=tracing::info_span!("operation",operation_id="tasks");
  let mut tasks=datafusion::common::runtime::JoinSet::new();
  root.in_scope(||{
   tasks.spawn(async{tracing::info!(boundary="async");});
   tasks.spawn_blocking(||{tracing::info!(boundary="blocking");});
   let captured=tracing::Span::current();
   tasks.spawn_blocking(move||captured.in_scope(||tracing::info!(boundary="blocking-explicit")));
  });
  while let Some(v)=tasks.join_next().await{v.unwrap();}
  drop(root);
 } else {
  let schema=Arc::new(Schema::new(vec![Field::new("n",DataType::Int64,false)]));
  let node=Arc::new(ProbeExec{inner:EmptyExec::new(schema),metrics:ExecutionPlanMetricsSet::new(),mode:mode.clone()});
  let physical=rule.optimize(node.clone(),&ConfigOptions::default())?;
  let (same_type,same_props)=(physical.is::<ProbeExec>(),Arc::ptr_eq(node.properties(),physical.properties()));
  let ctx=SessionContext::new_with_state(SessionStateBuilder::new().with_default_features().build());
  let root=tracing::info_span!("operation",operation_id=%mode);
  let mut stream=root.in_scope(||physical.execute(0,ctx.task_ctx()))?;
  let mut observed_rows=0; let mut status="eof";
  while let Some(next)=stream.next().instrument(root.clone()).await{
   match next {Ok(b)=>observed_rows+=b.num_rows(),Err(_)=>{status="error";break;}}
   if mode=="drop"{status="abandoned";break;}
  }
  drop(stream); drop(root);
  eprintln!("{}",serde_json::json!({"scenario":mode,"status":status,"rows":observed_rows,"native_metrics":physical.metrics().unwrap().to_string(),"same_type":same_type,"same_properties":same_props}));
 }
 println!("{}",buffer.take());
 Ok(())
}

